// GENERATED by scripts/build.mjs from dist/sales.css — do not edit.
// CSS-as-string: WebKitGTK cannot load link/fetch subresources from the
// about:srcdoc the shell mounts, so app.js injects this as an inline <style>.
export default "/* sales.css — domain residue for com.ikenga.sales.\n *\n * Only sales-local classes live here:\n *   - .sl-* Forecast view layout (.sl-forecast-kpis, .sl-forecast-kpi, etc.)\n *   - .sl-won-* Won view layout (.sl-won-wrap, .sl-won-table, .sl-won-badge)\n *   - Kanban + pipeline overrides specific to this domain (.kb-mini-avatar.is-agent,\n *     .split-row-when.is-urgent already in kit — no re-derive needed)\n *\n * Kit primitives (.frame*, .ip-split*, .dense-row*, .btn*, .tag, .chip, .badge,\n * .atelier-state*, .nav-group*, .nav-item*, .kb-*, .seg*, .split-*, etc.) are\n * consumed from app-kit-css.js — never re-derived here.\n *\n * Inject order: tokens-css → app-kit-css → sales-css (this file).\n * data-workspace=\"sessions\" on <html> → warm amber-ochre tint for active nav + accents.\n */\n\n/* ── Reduced motion gate ── */\n@media (prefers-reduced-motion: reduce) {\n  .split-row { transition: none; }\n  .kb-card { transition: none; }\n  .kb-card:hover { transform: none; }\n}\n\n/* ── Forecast view (.sl-*) ─────────────────────────────────────────────────── */\n\n.sl-forecast-wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  padding: 16px;\n  overflow-y: auto;\n  height: 100%;\n}\n\n.sl-forecast-kpis {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n  gap: 10px;\n}\n\n.sl-forecast-kpi {\n  background: var(--bg-surface, var(--bg-base));\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: 8px;\n  padding: 14px 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.sl-kpi-k {\n  font-family: var(--font-mono, monospace);\n  font-size: 10px;\n  font-weight: 500;\n  color: var(--fg-faint, var(--fg-muted));\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n}\n\n.sl-kpi-v {\n  font-family: var(--font-display, Georgia, serif);\n  font-size: 26px;\n  font-weight: 500;\n  font-style: normal;\n  color: var(--fg);\n  margin-top: 4px;\n}\n\n.sl-kpi-sub {\n  font-size: 0.7rem;\n  color: var(--fg-faint, var(--fg-muted));\n  font-family: var(--font-mono, monospace);\n}\n\n.sl-forecast-card {\n  background: var(--bg-surface, var(--bg-base));\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: 8px;\n  overflow: hidden;\n  /* The wrap is a scrolling flex column: without this the cards shrink to fit\n     a short pane and clip their rows instead of letting the wrap scroll. */\n  flex-shrink: 0;\n}\n\n.sl-forecast-card-h {\n  padding: 10px 14px;\n  font-size: 0.8rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.sl-funnel-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 14px;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.04));\n}\n\n.sl-funnel-row:last-child {\n  border-bottom: none;\n}\n\n.sl-funnel-name {\n  width: 100px;\n  font-size: 0.78rem;\n  color: var(--fg);\n  flex-shrink: 0;\n}\n\n.sl-funnel-bar {\n  flex: 1;\n  height: 22px;\n  border-radius: var(--radius-xs, 3px);\n  background: var(--bg-sunken, rgba(0,0,0,0.06));\n  position: relative;\n  overflow: hidden;\n}\n\n.sl-funnel-bar-fill {\n  position: absolute;\n  left: 0;\n  top: 0;\n  height: 100%;\n  background: var(--bg-raised, rgba(128,128,128,0.3));\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: var(--radius-xs, 3px);\n}\n\n.sl-funnel-bar-wt {\n  position: absolute;\n  left: 0;\n  top: 0;\n  height: 100%;\n  background: var(--primary, hsl(215,70%,55%));\n  border-radius: var(--radius-xs, 3px);\n  opacity: 0.9;\n}\n\n.sl-funnel-val {\n  width: 72px;\n  font-size: 0.72rem;\n  font-family: var(--font-mono, monospace);\n  color: var(--fg-muted);\n  text-align: right;\n  flex-shrink: 0;\n}\n\n.sl-months {\n  display: flex;\n  align-items: flex-end;\n  gap: 16px;\n  padding: 14px;\n  height: 170px;\n}\n\n.sl-month {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  flex: 1;\n  /* Full-height column so the bar's percentage height resolves against the\n     170px .sl-months container (mirrors the design's .fc-month { height:100% }).\n     Completes F-15 — without it the bar-wrap collapses to min-height and the\n     JS-percentage bars never scale. */\n  height: 100%;\n}\n\n.sl-month-bar-wrap {\n  flex: 1;\n  display: flex;\n  align-items: flex-end;\n  width: 100%;\n}\n\n.sl-month-bar {\n  width: 100%;\n  background: var(--primary, hsl(215,70%,55%));\n  border-radius: 3px 3px 0 0;\n  opacity: 0.7;\n  min-height: 4px;\n}\n\n.sl-month-val {\n  font-size: 0.65rem;\n  font-family: var(--font-mono, monospace);\n  color: var(--fg-muted);\n}\n\n.sl-forecast-note {\n  padding: 12px 14px;\n  font-size: 0.75rem;\n  line-height: 1.5;\n  color: var(--fg-muted);\n}\n\n.sl-month-lab {\n  font-size: 0.65rem;\n  color: var(--fg-faint, var(--fg-muted));\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n/* ── Won view (.sl-won-*) ───────────────────────────────────────────────────── */\n\n.sl-won-wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  padding: 16px;\n  overflow-y: auto;\n  height: 100%;\n}\n\n.sl-won-kpis {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n  gap: 10px;\n}\n\n.sl-won-table-wrap {\n  background: var(--bg-surface, var(--bg-base));\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.sl-won-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.8rem;\n}\n\n.sl-won-table thead tr {\n  background: var(--bg-inset, rgba(0,0,0,0.04));\n}\n\n.sl-won-table th {\n  padding: 8px 12px;\n  text-align: left;\n  font-size: 0.7rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n}\n\n.sl-won-table td {\n  padding: 9px 12px;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.04));\n  color: var(--fg);\n  vertical-align: middle;\n}\n\n.sl-won-table tbody tr:last-child td {\n  border-bottom: none;\n}\n\n.sl-won-table tbody tr:hover td {\n  background: var(--bg-hover, rgba(0,0,0,0.025));\n}\n\n.sl-won-badge {\n  display: inline-flex;\n  align-items: center;\n  padding: 2px 6px;\n  border-radius: 4px;\n  font-size: 0.65rem;\n  font-weight: 500;\n  background: var(--bg-inset, rgba(0,0,0,0.08));\n  color: var(--fg-muted);\n  text-transform: capitalize;\n  letter-spacing: 0.02em;\n}\n\n.sl-won-amt {\n  font-family: var(--font-mono, monospace);\n  font-size: 0.8rem;\n  font-weight: 600;\n  color: var(--live, hsl(150,48%,52%));\n}\n\n/* ── Kanban domain overrides ────────────────────────────────────────────────── */\n\n/* Stage dot colours per the screen doc */\n.kb-col[data-stage=\"lead\"] .kb-col-dot    { background: var(--fg-faint, rgba(128,128,128,0.4)); }\n.kb-col[data-stage=\"qualified\"] .kb-col-dot { background: var(--systemic, hsl(140,55%,42%)); }\n.kb-col[data-stage=\"proposal\"] .kb-col-dot  { background: var(--primary, hsl(215,70%,55%)); }\n.kb-col[data-stage=\"negotiation\"] .kb-col-dot { background: var(--achievement, hsl(38,85%,52%)); }\n.kb-col[data-stage=\"closing\"] .kb-col-dot  { background: var(--live, hsl(348,72%,52%)); }\n\n/* Deal row ux-mode dots */\n.ux-dot {\n  display: inline-block;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  flex-shrink: 0;\n  margin-right: 4px;\n}\n.ux-dot.ux-confirm  { background: var(--achievement, hsl(38,85%,52%)); }\n.ux-dot.ux-silent   { background: var(--fg-faint, rgba(128,128,128,0.4)); }\n.ux-dot.ux-approve  { background: var(--primary, hsl(215,70%,55%)); }\n\n/* Next-action chip in list rows */\n.next-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n  font-size: 0.68rem;\n  color: var(--fg-muted);\n  background: var(--bg-inset, rgba(0,0,0,0.06));\n  border-radius: 4px;\n  padding: 2px 6px;\n  max-width: 180px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* Stage chip in detail pane */\n.stage-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  font-size: 0.7rem;\n  font-weight: 600;\n  padding: 3px 8px;\n  border-radius: 5px;\n  background: var(--bg-inset, rgba(0,0,0,0.07));\n  color: var(--fg-muted);\n  text-transform: capitalize;\n  letter-spacing: 0.03em;\n}\n\n/* Hot filter (Closing soon — achievement tint) */\n.nav-item.is-hot .nav-item-count {\n  color: var(--achievement, hsl(38,85%,52%));\n  font-weight: 700;\n}\n\n/* Deal amount in list rows */\n.split-row-amt {\n  font-family: var(--font-mono, monospace);\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: var(--fg);\n  white-space: nowrap;\n}\n\n/* Age / urgency */\n.split-row-when {\n  font-size: 0.68rem;\n  color: var(--fg-faint, var(--fg-muted));\n  font-family: var(--font-mono, monospace);\n  white-space: nowrap;\n}\n\n.split-row-when.is-urgent {\n  color: var(--danger, hsl(0,65%,52%));\n}\n\n/* F-03 · Selected-row accent rail → explicit warm-primary (design uses\n   var(--primary), not the sessions amber-ochre --tint-fg-active). */\n.split-row.is-selected .split-row-accent,\n.split-row.is-on .split-row-accent {\n  background: var(--primary, hsl(20,50%,34%));\n  border-radius: 2px;\n}\n\n/* F-02 · Pipeline list-pane head — sticky Fraunces \"Sales\" title + mono\n   count above the stage groups. Ported from the design's .pl-list-head /\n   .pl-list-title / .pl-list-meta (not an app-kit primitive). */\n.sl-list-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: var(--space-3, 12px) var(--space-4, 16px);\n  border-bottom: 1px solid var(--border-soft);\n  position: sticky;\n  top: 0;\n  background: var(--bg-surface);\n  z-index: 6;\n}\n\n.sl-list-title {\n  font-family: var(--font-display, Georgia, serif);\n  font-weight: 500;\n  font-size: var(--text-h3, 18px);\n  color: var(--fg);\n}\n\n.sl-list-meta {\n  font-family: var(--font-mono, monospace);\n  font-size: 10.5px;\n  color: var(--fg-faint, var(--fg-muted));\n  letter-spacing: 0.04em;\n}\n\n/* F-05 · Detail-pane title → Fraunces 28px (design spec). The app-kit\n   primitive sets Fraunces at --text-h2 (24px); sales bumps it to 28px to\n   match the locked sales design's .pl-detail-title. */\n.split-detail-title {\n  font-family: var(--font-display, Georgia, serif);\n  font-size: 28px;\n  font-weight: 500;\n  line-height: 1.15;\n  letter-spacing: -0.012em;\n  color: var(--fg);\n  margin: 0 0 var(--space-2, 8px);\n}\n\n/* F-06 / F-07 / F-08 · The facts grid (3-col card), next-action card\n   (live-tinted border + bg), and next-action head (UPPERCASE mono 10px)\n   are all consumed verbatim from the app-kit primitives (.split-facts,\n   .split-next, .split-next-head) — no sales-local override. The previous\n   2-col plain-grid / un-tinted overrides were drift and have been removed\n   so the kit's design-correct rules apply. */\n\n/* Activity timeline in detail pane */\n.split-timeline {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-top: 12px;\n}\n\n.split-tl-row {\n  display: flex;\n  gap: 10px;\n  align-items: flex-start;\n}\n\n.split-tl-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--fg-faint, rgba(128,128,128,0.4));\n  flex-shrink: 0;\n  margin-top: 5px;\n}\n\n.split-tl-body {\n  flex: 1;\n}\n\n.split-tl-title {\n  font-size: 0.78rem;\n  color: var(--fg);\n}\n\n.split-tl-when {\n  font-size: 0.65rem;\n  color: var(--fg-faint, var(--fg-muted));\n  font-family: var(--font-mono, monospace);\n}\n\n/* Seg toggle (list/kanban) injected into sidebar nav-group */\n.nav-view-seg {\n  margin: 4px 8px 6px;\n}\n\n/* Kanban board horizontal scroll mask */\n.kb-board-wrap {\n  overflow-x: auto;\n  height: 100%;\n  -webkit-mask-image: linear-gradient(to right, black calc(100% - 40px), transparent 100%);\n  mask-image: linear-gradient(to right, black calc(100% - 40px), transparent 100%);\n}\n"
